output_text:
[
  {
    "id": "take_start_cart",
    "text": "A shopper is obliged to take the store cart from the entrance cart station before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "cart_for_item_pickups",
    "text": "It is forbidden to pick up merchandise unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "It is forbidden to carry shopping items by hand instead of placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_goods": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_carrying_goods"
    }
  },
  {
    "id": "return_cart_front_left",
    "text": "After taking a cart, the shopper is obliged to return and leave it at the front-left cart return bay.",
    "abstraction": {
      "state_properties": {
        "front_left_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "pickup_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "front_left_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_leave_cart_at_bay",
    "text": "It is forbidden to leave the cart anywhere except the designated front-left return bay.",
    "abstraction": {
      "state_properties": {
        "front_left_return_bay": "at(0,1)"
      },
      "events": {
        "misplaced_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "hasCart",
              {
                "not": "front_left_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "misplaced_cart_drop"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to leave the store while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "store_exit_cell": "at(9,5)"
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "store_exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cart_free_exit_zone",
    "text": "It is forbidden to push a cart into the pedestrian-only exit zone on the right side of the store.",
    "abstraction": {
      "state_properties": {
        "pedestrian_exit_zone": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)",
            "at(9,4)",
            "at(9,3)",
            "at(9,2)",
            "at(8,4)",
            "at(8,3)",
            "at(8,2)"
          ]
        },
        "cart_in_pedestrian_exit_zone": {
          "and": [
            "hasCart",
            "pedestrian_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_pedestrian_exit_zone"
    }
  },
  {
    "id": "pickup_only_from_service_cells",
    "text": "It is forbidden to pick up an item except from one of the recognized shelf-facing service cells for the product sections.",
    "abstraction": {
      "state_properties": {
        "apple_service_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)"
          ]
        },
        "bread_service_cell": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_service_cell": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "egg_service_cell": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "recognized_product_service_cell": {
          "or": [
            "apple_service_cell",
            "bread_service_cell",
            "milk_service_cell",
            "egg_service_cell"
          ]
        }
      },
      "events": {
        "pickup_outside_product_service_cell": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "recognized_product_service_cell"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_outside_product_service_cell"
    }
  }
]
